// Fixtures are generated by installed native Plan + Apply + StateEncoding using
// inert local providers. No Cloudflare/GitHub network capability is installed.
import { afterEach, describe, expect, it, vi } from "vitest";
import * as NodeServices from "@effect/platform-node/NodeServices";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Redacted from "effect/Redacted";
import * as Duration from "effect/Duration";
import * as Output from "alchemy/Output";
import * as Provider from "alchemy/Provider";
import { Resource } from "alchemy/Resource";
import { Action } from "alchemy/Action";
import * as Plan from "alchemy/Plan";
import * as Apply from "alchemy/Apply";
import { RemovalPolicy } from "alchemy/RemovalPolicy";
import { Stack, type StackSpec } from "alchemy/Stack";
import { Stage } from "alchemy/Stage";
import { State, type PersistedState } from "alchemy/State/State";
import { InMemoryService } from "alchemy/State/InMemoryState";
import { encodeState } from "alchemy/State/StateEncoding";
import { ACCOUNT, STACK, acquireHttpSnapshot, acquireSnapshot } from "../deploy/planning-state.ts";
import { decodeNativeState } from "../deploy/native-state-decoder.ts";

const target = { stack: STACK, stage: "prod" } as const;
const secret = "NATIVE_REDACTED_CANARY";
type Props = Record<string, unknown>;
type Attr = Record<string, unknown>;
const DB = Resource<Resource<"Cloudflare.D1Database", Props, Attr>>("Cloudflare.D1Database");
const Worker = Resource<Resource<"Cloudflare.Worker", Props, Attr>>("Cloudflare.Worker");
const AppSecret = Resource<Resource<"GQSupport.GitHubAppSecret", Props, Attr>>("GQSupport.GitHubAppSecret");
const providers = Layer.mergeAll(
  Provider.succeed(DB, { version: 1, diff: () => Effect.succeed(undefined), reconcile: ({ id }) => Effect.succeed({
    accountId: ACCOUNT, jurisdiction: "eu", databaseName: `fixture-${id}`, migrationsHashes: {},
    databaseId: `00000000-0000-4000-8000-00000000000${id === "SupportDB" ? "1" : "2"}`,
  }), delete: () => Effect.die(new Error("Fixture delete forbidden")) }),
  Provider.succeed(Worker, { version: 1, diff: () => Effect.succeed(undefined), reconcile: () => Effect.succeed({ workerName: "synthetic-worker", url: "https://synthetic.invalid" }), delete: () => Effect.die(new Error("Fixture delete forbidden")) }),
  Provider.succeed(AppSecret, { diff: () => Effect.succeed(undefined), reconcile: () => Effect.succeed({ appId: 1, checkedAt: "2026-10-27T00:00:00.000Z" }), delete: () => Effect.die(new Error("Fixture delete forbidden")) }),
);
const declaration = Effect.gen(function* () {
  const db = yield* DB("SupportDB", { jurisdiction: "eu" });
  const ledger = yield* DB("SupportLedger", { jurisdiction: "eu" });
  const worker = yield* Worker("Worker", { database: db.databaseId, ledger: ledger.databaseId, confidential: Redacted.make(secret),
    duration: Duration.seconds(3), date: new Date("2026-10-27T00:00:00.000Z") });
  yield* AppSecret("GitHubAppSecret", { stage: "prod", workerName: Output.map(Output.of(worker), (attr) => attr.workerName) });
  yield* Action("FixtureReadAction", (_input: { worker: string }) => Effect.succeed({ ok: true }))({ worker: worker.workerName as Output.Output<string> });
  return { workerName: worker.workerName, databaseId: db.databaseId, ledgerId: ledger.databaseId, confidential: Redacted.make(secret) };
});
function stack(): StackSpec { return { name: STACK, stage: "prod", resources: {}, actions: {}, bindings: {}, output: {} }; }
async function fixture() {
  const memory = await Effect.runPromise(InMemoryService());
  const first = stack();
  await Effect.runPromise(Effect.gen(function* () {
    first.output = yield* declaration;
    yield* Apply.apply(yield* Plan.make(first));
  }).pipe(Effect.provideService(Stack, first), Effect.provideService(Stage, "prod"),
    Effect.provideService(RemovalPolicy, "retain"), Effect.provideService(State, Effect.succeed(memory)),
    Effect.provide(providers), Effect.provide(NodeServices.layer)));
  const rows = new Map<string, PersistedState>();
  for (const fqn of await Effect.runPromise(memory.list(target))) {
    const row = await Effect.runPromise(memory.get({ ...target, fqn }));
    if (!row) throw new Error("Native fixture row missing");
    rows.set(fqn, row);
  }
  const output = await Effect.runPromise(memory.getOutput(target));
  // Exact native persistence wire, including marker wrapping before JSON.
  const wire = (v: unknown): unknown => JSON.parse(JSON.stringify(encodeState(v)));
  const transport = vi.fn<typeof fetch>(async (input, init) => {
    expect(init?.method).toBe("GET"); expect(init?.redirect).toBe("error");
    const path = new URL(String(input)).pathname;
    const data = path === "/version" ? { version: 7 } : path.endsWith("/stages") ? ["prod"] :
      path.endsWith("/resources") ? [...rows.keys()] : path.endsWith("/replaced-resources") ? [] :
      path.endsWith("/output") ? wire(output) : wire(rows.get(decodeURIComponent(path.split("/").at(-1)!)));
    return Response.json(data);
  });
  return { memory, rows, output, wire, transport, resources: first.resources };
}
afterEach(() => vi.restoreAllMocks());
describe("actual beta.83 native encoding fixtures", () => {
  it("roundtrips engine-generated Worker, D1, GitHubAppSecret and settled action graph through confined HTTP", async () => {
    const bypass = vi.spyOn(globalThis, "fetch").mockRejectedValue(new Error(secret));
    const f = await fixture();
    expect([...f.rows.keys()].sort()).toEqual(["FixtureReadAction", "GitHubAppSecret", "SupportDB", "SupportLedger", "Worker"]);
    expect(f.wire(f.rows.get("Worker"))).toMatchObject({ props: { confidential: { __redacted__: secret }, duration: { __duration__: { _id: "Duration", _tag: "Millis", millis: 3000 } }, date: { __date__: "2026-10-27T00:00:00.000Z" } } });
    const snapshot = await Effect.runPromise(acquireHttpSnapshot({ origin: "https://state.invalid", account: ACCOUNT, script: "synthetic", scriptDigest: "a".repeat(64), protocol: 7, target }, "synthetic-state-canary", f.transport));
    const worker = await Effect.runPromise(snapshot.get({ ...target, fqn: "Worker" }));
    if (!worker || worker.kind === "action") throw new Error("Expected resource");
    expect(Redacted.value(worker.props!.confidential)).toBe(secret);
    expect(Duration.toMillis(worker.props!.duration)).toBe(3000);
    expect(worker.props!.date.toISOString()).toBe("2026-10-27T00:00:00.000Z");
    expect(JSON.stringify(worker)).not.toContain(secret);
    expect(Object.isFrozen(worker.props)).toBe(true);
    expect(() => { worker.props!.confidential = "changed"; }).toThrow();
    worker.props!.date.setTime(0); Redacted.wipeUnsafe(worker.props!.confidential);
    const again = await Effect.runPromise(snapshot.get({ ...target, fqn: "Worker" }));
    if (!again || again.kind === "action") throw new Error("Expected resource");
    expect(again.props!.date.toISOString()).toBe("2026-10-27T00:00:00.000Z");
    expect(Redacted.value(again.props!.confidential)).toBe(secret);
    // Genuine native planner consumes the decoded graph without running any
    // full live provider or receiving a network/write State capability.
    const next = stack();
    const plan = await Effect.runPromise(Effect.gen(function* () {
      next.output = yield* declaration;
      return yield* Plan.make(next);
    }).pipe(Effect.provideService(Stack, next), Effect.provideService(Stage, "prod"),
      Effect.provideService(State, Effect.succeed(snapshot)), Effect.provideService(RemovalPolicy, "retain"),
      Effect.provide(providers), Effect.provide(NodeServices.layer)));
    expect(Object.values(plan.resources).map((node) => node.action)).toEqual(["noop", "noop", "noop", "noop"]);
    expect(plan.actions.FixtureReadAction.action).toBe("noop");
    expect(bypass).not.toHaveBeenCalled();
  });
  it("validates native flattened resources and resolves in-memory native references against exact rows", async () => {
    const f = await fixture();
    const graph = { target, rows: f.rows, output: f.output };
    const resource = f.resources.SupportDB;
    const flattened = f.wire(resource);
    expect(flattened).toMatchObject({ id: "SupportDB", type: DB.Type, props: { jurisdiction: "eu" } });
    expect(flattened).not.toHaveProperty("attr");
    expect(decodeNativeState(flattened, graph)).toEqual(flattened);
    const expressions: unknown[] = [
      new Output.PropExpr<Record<string, unknown>, string, never>(new Output.ResourceExpr<Record<string, unknown>>(resource), "databaseId"),
      new Output.PropExpr<Record<string, unknown>, string, never>(new Output.RefExpr<Record<string, unknown>>(STACK, "prod", "SupportDB", { Type: DB.Type }), "databaseId"),
      new Output.PropExpr<Record<string, unknown>, string, never>(new Output.StackRefExpr<Record<string, unknown>>(STACK, "prod"), "workerName"),
      Output.all(Output.literal("value"), Output.named(new Output.PropExpr<Record<string, unknown>, string, never>(new Output.RefExpr<Record<string, unknown>>(undefined, undefined, "Worker"), "workerName"), "label"))];
    for (const expression of expressions) {
      const expected = await Effect.runPromise(Output.evaluate<unknown>(expression, Object.fromEntries([...f.rows].map(([fqn, row]) => [fqn, row.kind === "action" ? (row.status === "ran" ? row.output : undefined) : row.attr]))).pipe(Effect.provideService(State, Effect.succeed(f.memory)), Effect.provideService(Stack, stack()), Effect.provideService(Stage, "prod")));
      // Installed encoder returns a function proxy; JSON cannot persist it.
      // Do not invent a tagged JSON expression to hide this limitation.
      expect(typeof encodeState(expression)).toBe("function");
      expect(JSON.stringify(encodeState(expression))).toBeUndefined();
      expect(decodeNativeState(expression, graph)).toEqual(expected);
    }
  });
  it.each(["map", "effect", "flatMap"])("never invokes %s native callback behavior", async (kind) => {
    const f = await fixture();
    const callback = vi.fn(() => "forbidden");
    const expression = kind === "map" ? Output.map(Output.literal(1), callback) :
      kind === "effect" ? Output.fromEffect(Effect.sync(callback)) :
        Output.flatMap(Output.literal(1), () => { callback(); return Output.literal("forbidden"); });
    expect(() => decodeNativeState(expression, { target, rows: f.rows, output: f.output })).toThrow("Protected planning evidence unavailable; apply blocked");
    expect(callback).not.toHaveBeenCalled();
  });
  it.each(["stack", "stage", "path", "missing", "type", "callback", "cycle"])("rejects native encoded %s reference or lost executable behavior", async (failure) => {
    const f = await fixture();
    const ref = new Output.RefExpr(failure === "stack" ? "Other" : STACK, failure === "stage" ? "staging" : "prod",
      failure === "missing" ? "Absent" : failure === "path" ? "../Worker" : "Worker", { Type: failure === "type" ? DB.Type : Worker.Type });
    const value = failure === "callback" ? Output.map(Output.literal(1), (v) => v + 1) : ref;
    const output = failure === "cycle" ? new Output.StackRefExpr(STACK, "prod") : f.output;
    expect(() => decodeNativeState(failure === "cycle" ? new Output.StackRefExpr(STACK, "prod") : value, { target, rows: f.rows, output })).toThrow("Protected planning evidence unavailable; apply blocked");
  });
  it.each(["mixed-marker", "bad-duration", "bad-date", "tag", "prototype", "cycle", "depth", "size", "accessor", "expression-claim"])("refuses malformed %s without leaking values", async (failure) => {
    const f = await fixture();
    let value: unknown;
    if (failure === "mixed-marker") value = { __redacted__: secret, extra: true };
    if (failure === "bad-duration") value = { __duration__: { _id: "Duration", _tag: "Nanos", nanos: secret } };
    if (failure === "bad-date") value = { __date__: secret };
    if (failure === "tag") value = { _tag: secret };
    if (failure === "prototype") value = JSON.parse('{"__proto__":{"value":"bad"}}');
    if (failure === "cycle") { const cycle: unknown[] = []; cycle.push(cycle); value = cycle; }
    if (failure === "depth") { value = secret; for (let i = 0; i < 65; i++) value = { nested: value }; }
    if (failure === "size") value = "x".repeat(8 * 1024 * 1024 + 1);
    if (failure === "expression-claim") value = { kind: "RefExpr", stack: STACK, stage: "prod", resourceId: "Worker" };
    if (failure === "accessor") value = Object.defineProperty({}, "hidden", { enumerable: true, get: () => { throw new Error(secret); } });
    expect(() => decodeNativeState(value, { target, rows: f.rows, output: f.output })).toThrow("Protected planning evidence unavailable; apply blocked");
  });
  it.each(["vanished", "unsettled", "identity", "mode", "action", "history", "schemaAny", "empty"])("rejects %s in native-generated state", async (failure) => {
    const f = await fixture();
    const state = { ...f.memory, getVersion: () => Effect.succeed(7) };
    if (failure === "vanished") state.get = () => Effect.succeed(undefined);
    else if (failure === "empty") state.list = () => Effect.succeed([]);
    else {
      const row = f.rows.get(failure === "action" ? "FixtureReadAction" : "SupportLedger")!;
      const changed = { ...row };
      if (failure === "unsettled") Object.assign(changed, { status: "updating" });
      if (failure === "identity") Object.assign(changed, { instanceId: undefined });
      if (failure === "mode") Object.assign(changed, { providerMode: "local" });
      if (failure === "action") Object.assign(changed, { inputHash: undefined });
      if (failure === "history") Object.assign(changed, { old: row });
      await Effect.runPromise(state.set({ ...target, fqn: row.fqn, value: failure === "schemaAny" ? {} as PersistedState : changed }));
    }
    await expect(Effect.runPromise(acquireSnapshot(state, target))).rejects.toThrow("Protected planning evidence unavailable; apply blocked");
  });
});

it.each([
  '{"version":7,"__proto__":{"secret":"NATIVE_REDACTED_CANARY"}}',
  '{"__duration__":{"_id":"Duration","_tag":"Nanos","nanos":"NATIVE_REDACTED_CANARY"}}',
  '{"__redacted__":"NATIVE_REDACTED_CANARY","extra":true}',
])("refuses malformed wire before native schema/revival without recovery", async (body) => {
  const bypass = vi.spyOn(globalThis, "fetch").mockRejectedValue(new Error(secret));
  const log = vi.spyOn(console, "log").mockImplementation(() => {});
  const error = vi.spyOn(console, "error").mockImplementation(() => {});
  const transport = vi.fn<typeof fetch>(async (_input, init) => {
    expect(init?.method).toBe("GET"); expect(init?.redirect).toBe("error");
    return new Response(body, { headers: { "content-type": "application/json" } });
  });
  try {
    await Effect.runPromise(acquireHttpSnapshot({ origin: "https://state.invalid", account: ACCOUNT, script: "synthetic", scriptDigest: "a".repeat(64), protocol: 7, target }, "synthetic-state-canary", transport));
    throw new Error("Expected refusal");
  } catch (e) {
    expect(String(e)).toBe("Error: Protected planning evidence unavailable; apply blocked");
    expect(String(e)).not.toContain(secret);
  }
  expect(transport).toHaveBeenCalledOnce(); expect(bypass).not.toHaveBeenCalled();
  expect(log).not.toHaveBeenCalled(); expect(error).not.toHaveBeenCalled();
});
